package com.akshaykadam.pixelboard.extension.updater;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.drawable.Icon;
import android.util.Base64;

/**
 * The Bou mark (a spoken wave that becomes the matra of ব), embedded as PNG because the patched
 * app's resources come from the Gboard base. Source art: docs/logo/make_logo.py.
 */
public final class BouBrand {

    /** Full app icon, 192 px, violet with the white mark. */
    private static final String APP_ICON_PNG = "";

    /** White mark on transparent, 96 px, for the status bar. */
    private static final String NOTIFICATION_PNG = "";

    private BouBrand() {
    }

    public static Bitmap appIcon() {
        return decode(APP_ICON_PNG);
    }

    public static Icon notificationIcon() {
        return Icon.createWithBitmap(decode(NOTIFICATION_PNG));
    }

    private static Bitmap decode(String b64) {
        byte[] bytes = Base64.decode(b64, Base64.DEFAULT);
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
    }
}
